import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().exec();
    }

    void exec() {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = sc.nextInt();
        int k = sc.nextInt();

        int[] poly = new int[10];
        for (int i = 0; i < k; i++) {
            poly[sc.nextInt()] = 1;
        }

        int[] result = new int[]{1};
        int exponent = n / 2;

        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = convolute(result, poly, MOD);
            }
            poly = convolute(poly, poly, MOD);
            exponent >>= 1;
        }

        long answer = 0;
        for (int val : result) {
            answer = (answer + (long)val * val) % MOD;
        }
        pw.println(answer);
        pw.close();
    }

    int[] convolute(int[] p, int[] q, int mod) {
        int len = p.length + q.length - 1;
        int n = Integer.highestOneBit(len - 1) << 1;
        if (n < 2) n = 2;

        double[] pr = new double[n];
        double[] pi = new double[n];
        for (int i = 0; i < p.length; i++) {
            long x = (p[i] % mod + mod) % mod;
            pr[i] = x & 0x7FFF;
            pi[i] = x >>> 15;
        }
        transform(pr, pi, false);

        double[] qr = new double[n];
        double[] qi = new double[n];
        for (int i = 0; i < q.length; i++) {
            long x = (q[i] % mod + mod) % mod;
            qr[i] = x & 0x7FFF;
            qi[i] = x >>> 15;
        }
        transform(qr, qi, false);

        double[] cr = new double[n];
        double[] ci = new double[n];
        double[] dr = new double[n];
        double[] di = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double a1r = (pr[i] + pr[j]) * 0.5;
            double a1i = (pi[i] - pi[j]) * 0.5;
            double a2r = (pi[i] + pi[j]) * 0.5;
            double a2i = (pr[j] - pr[i]) * 0.5;

            double b1r = (qr[i] + qr[j]) * 0.5;
            double b1i = (qi[i] - qi[j]) * 0.5;
            double b2r = (qi[i] + qi[j]) * 0.5;
            double b2i = (qr[j] - qr[i]) * 0.5;

            cr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            ci[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            dr[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            di[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        transform(cr, ci, true);
        transform(dr, di, true);

        int[] res = new int[len];
        for (int i = 0; i < len; i++) {
            long a = Math.round(cr[i]);
            long b = Math.round(dr[i]);
            long c = Math.round(ci[i]);
            res[i] = (int)((a + ((b % mod) << 15) + ((c % mod) << 30)) % mod);
        }
        return res;
    }

    void transform(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j ^= bit) < bit; bit >>>= 1);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int h = 2; h <= n; h <<= 1) {
            double ang = 2 * Math.PI / h * (inverse ? -1 : 1);
            double wH_re = Math.cos(ang);
            double wH_im = Math.sin(ang);

            for (int i = 0; i < n; i += h) {
                double w_re = 1;
                double w_im = 0;
                for (int j = 0; j < h / 2; j++) {
                    double ur = re[i + j];
                    double ui = im[i + j];
                    double vr = re[i + j + h/2] * w_re - im[i + j + h/2] * w_im;
                    double vi = re[i + j + h/2] * w_im + im[i + j + h/2] * w_re;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + h/2] = ur - vr;
                    im[i + j + h/2] = ui - vi;

                    double t_re = w_re * wH_re - w_im * wH_im;
                    w_im = w_re * wH_im + w_im * wH_re;
                    w_re = t_re;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        int nextInt() {
            int c = read();
            while (c <= ' ') c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new IndexOutOfBoundsException();
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        private int read() {
            if (ptr >= len) {
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xff;
        }
    }
}
